UPDATE agent_schedule_task
SET tenant_id = #{tenantId}, user_id = #{userId}, config_id = #{configId}, task_id = #{taskId}, planned_time = #{plannedTime}, status = #{status}, retry_count = #{retryCount}, metadata = #{metadata}
WHERE id = #{id} AND deleted = 0

UPDATE agent_schedule_task SET lease_until = #{leaseUntil}, row_version = row_version + 1
WHERE task_id = #{taskId} AND lease_owner = #{leaseOwner} AND fencing_token = #{fencingToken}
  AND status = 'running' AND deleted = 0
